    39  int io_memory_write(RIO *io, RIODesc *fd, const ut8 *buf, int count) {
    40          r_return_val_if_fail (io && fd && buf, -1);
    41          if (count < 0 || !fd->data) {
    42                  return -1;
    43          }
    44          if (_io_malloc_off (fd) > _io_malloc_sz (fd)) {
    45                  return -1;
    46          }
    47          if (_io_malloc_off (fd) + count > _io_malloc_sz (fd)) {
    48                  count -= (_io_malloc_off (fd) + count -_io_malloc_sz (fd));
    49          }
    50          if (count > 0) {
    51                  memcpy (_io_malloc_buf (fd) + _io_malloc_off (fd), buf, count);
    52                  _io_malloc_set_off (fd, _io_malloc_off (fd) + count);
    53                  return count;
    54          }
    55          return -1;
    56  }
