    58  bool io_memory_resize(RIO *io, RIODesc *fd, ut64 count) {
    59          r_return_val_if_fail (io && fd, false);
    60          if (count == 0) { // TODO: why cant truncate to 0 bytes
    61                  return false;
    62          }
    63          ut32 mallocsz = _io_malloc_sz (fd);
    64          if (_io_malloc_off (fd) > mallocsz) {
    65                  return false;
    66          }
    67          RIOMalloc *mal = (RIOMalloc*)fd->data;
    68          ut8 *new_buf = realloc (mal->buf, count);
    69          if (!new_buf) {
    70                  return false;
    71          }
    72          mal->buf = new_buf;
    73          if (count > mal->size) {
    74                  memset (mal->buf + mal->size, 0, count - mal->size);
    75          }
    76          mal->size = count;
    77          return true;
    78  }
