    80  int io_memory_read(RIO *io, RIODesc *fd, ut8 *buf, int count) {
    81          r_return_val_if_fail (io && fd && buf, -1);
    82          memset (buf, 0xff, count);
    83          if (!fd->data) {
    84                  return -1;
    85          }
    86          ut32 mallocsz = _io_malloc_sz (fd);
    87          if (_io_malloc_off (fd) > mallocsz) {
    88                  return -1;
    89          }
    90          if (_io_malloc_off (fd) + count >= mallocsz) {
    91                  count = mallocsz - _io_malloc_off (fd);
    92          }
    93          memcpy (buf, _io_malloc_buf (fd) + _io_malloc_off (fd), count);
    94          _io_malloc_set_off (fd, _io_malloc_off (fd) + count);
    95          return count;
    96  }
