    98  bool io_memory_close(RIODesc *fd) {
    99          if (!fd || !fd->data) {
   100                  return false;
   101          }
   102          RIOMalloc *riom = fd->data;
   103          R_FREE (riom->buf);
   104          R_FREE (fd->data);
   105          return true;
