   108  ut64 io_memory_lseek(RIO* io, RIODesc *fd, ut64 offset, int whence) {
   109          r_return_val_if_fail (io && fd, offset);
   110          ut64 r_offset = offset;
   111          if (!fd || !fd->data) {
   112                  return offset;
   113          }
   114          ut32 mallocsz = _io_malloc_sz (fd);
   115          switch (whence) {
   116          case SEEK_SET:
   117                  r_offset = (offset <= mallocsz) ? offset : mallocsz;
   118                  break;
   119          case SEEK_CUR:
   120                  r_offset = (_io_malloc_off (fd) + offset <= mallocsz ) ? _io_malloc_off (fd) + offset : mallocsz;
   121                  break;
   122          case SEEK_END:
   123                  r_offset = _io_malloc_sz (fd);
   124                  break;
   125          }
   126          _io_malloc_set_off (fd, r_offset);
   127          return r_offset;
   128  }
